// Contract for Atelier's modular companion system. Shared by the asset
// generator (scripts/companion-assets), the renderer runtime
// (src/renderer/src/companion) and main (profile storage, presets).
// All art is original and generated by code; see docs/companion-system.md.

// ---- base rigs ----

/** A: round "Bean", B: tall "Sprout", C: small "Pebble". */
export const RIGS = ['A', 'B', 'C'] as const
export type RigId = (typeof RIGS)[number]

/** Nodes every rig animates. Clips target these names. */
export const RIG_NODES = ['root', 'body', 'head-pivot', 'arm.L', 'arm.R', 'foot.L', 'foot.R'] as const

// ---- 3D part slots ----

export const PART_SLOTS = ['head', 'ears', 'hair', 'hat', 'eyeAccessory', 'earAccessory', 'prop'] as const
export type PartSlot = (typeof PART_SLOTS)[number]

/**
 * Empty nodes named `anchor:<name>` that parts attach to. The rig carries
 * `head` and `prop`; every head part carries the rest, so per-head geometry
 * decides where hats, hair and accessories sit.
 */
export const ANCHORS = ['head', 'prop', 'hat', 'hair', 'ears', 'eyeAccessory', 'earAccessory'] as const
export type AnchorName = (typeof ANCHORS)[number]

/** Which anchor each slot attaches to. */
export const SLOT_ANCHOR: Record<PartSlot, AnchorName> = {
  head: 'head',
  ears: 'ears',
  hair: 'hair',
  hat: 'hat',
  eyeAccessory: 'eyeAccessory',
  earAccessory: 'earAccessory',
  prop: 'prop',
}

/** Materials named `tint:<tint>` are recoloured from the profile. */
export const TINTS = ['skin', 'hair', 'accent', 'outfit'] as const
export type Tint = (typeof TINTS)[number]

/** The part catalogue. The generator must produce exactly these ids. */
export const PART_IDS = {
  head: ['head-round', 'head-oval', 'head-soft-square', 'head-drop', 'head-bean', 'head-cloud'],
  ears: ['ears-cat', 'ears-bear', 'ears-bunny', 'ears-elf'],
  hair: ['hair-tuft', 'hair-bob', 'hair-spiky', 'hair-curls', 'hair-bun', 'hair-sideswept', 'hair-pigtails', 'hair-mohawk'],
  hat: ['hat-beanie', 'hat-cap', 'hat-crown', 'hat-wizard', 'hat-beret', 'hat-flower-crown'],
  eyeAccessory: ['glasses-round', 'glasses-square', 'monocle', 'visor'],
  earAccessory: ['headphones', 'earring-hoop', 'earring-star'],
  prop: ['prop-coffee', 'prop-book', 'prop-laptop', 'prop-wand', 'prop-magnifier', 'prop-balloon', 'prop-keypad'],
} as const satisfies Record<PartSlot, readonly string[]>

/**
 * GA-25: the prop the companion holds while the agent does a kind of step:
 * a book while reading, a magnifier while searching, a typing pad while it
 * fills in forms. Atelier's own generated parts, from the same catalogue.
 */
export const ACTIVITY_PROP_PART = {
  reading: 'prop-book',
  searching: 'prop-magnifier',
  typing: 'prop-keypad',
} as const satisfies Record<string, (typeof PART_IDS)['prop'][number]>

// ---- 2D face layer ----

/** The face is drawn on a 512×256 canvas mapped onto each head's `face` mesh. */
export const FACE_CANVAS = { width: 512, height: 256 } as const

export const FACE_LAYERS = ['eyes', 'brows', 'mouth'] as const
export type FaceLayer = (typeof FACE_LAYERS)[number]

export const EYE_VARIANTS = ['neutral', 'blink', 'happy', 'focused', 'wide', 'sad', 'sleepy'] as const
export const BROW_VARIANTS = ['neutral', 'raised', 'furrowed', 'sad'] as const
export const MOUTH_VARIANTS = ['neutral', 'happy', 'talk-small', 'talk-wide', 'o', 'sad', 'flat'] as const
export type EyeVariant = (typeof EYE_VARIANTS)[number]
export type BrowVariant = (typeof BROW_VARIANTS)[number]
export type MouthVariant = (typeof MOUTH_VARIANTS)[number]

export const FACE_IDS = {
  eyes: ['eyes-round', 'eyes-oval', 'eyes-sparkle', 'eyes-sleepy', 'eyes-dot', 'eyes-wide', 'eyes-cat', 'eyes-lash'],
  brows: ['brows-soft', 'brows-bold', 'brows-thin', 'brows-none'],
  mouth: ['mouth-smile', 'mouth-cat', 'mouth-grin', 'mouth-small', 'mouth-fang'],
} as const satisfies Record<FaceLayer, readonly string[]>

// ---- moods, clips, expressions ----

export const COMPANION_MOODS = ['idle', 'listening', 'thinking', 'working', 'talking', 'approval', 'happy', 'sad', 'sleeping'] as const
export type CompanionMood = (typeof COMPANION_MOODS)[number]

/** Looping clips (one per mood) plus one-shots. Every rig has all of them. */
export const CLIPS = ['idle', 'listen', 'think', 'work', 'talk', 'alert', 'celebrate', 'sad', 'sleep', 'wave', 'poke'] as const
export type ClipId = (typeof CLIPS)[number]
export const ONE_SHOT_CLIPS: readonly ClipId[] = ['wave', 'poke']

export const MOOD_CLIP: Record<CompanionMood, ClipId> = {
  idle: 'idle',
  listening: 'listen',
  thinking: 'think',
  working: 'work',
  talking: 'talk',
  approval: 'alert',
  happy: 'celebrate',
  sad: 'sad',
  sleeping: 'sleep',
}

export interface FaceState {
  eyes: EyeVariant
  brows: BrowVariant
  mouth: MouthVariant
}

/** Resting expression per mood; animation events and talking override it briefly. */
export const MOOD_FACE: Record<CompanionMood, FaceState> = {
  idle: { eyes: 'neutral', brows: 'neutral', mouth: 'neutral' },
  listening: { eyes: 'wide', brows: 'raised', mouth: 'happy' },
  thinking: { eyes: 'focused', brows: 'furrowed', mouth: 'flat' },
  working: { eyes: 'focused', brows: 'neutral', mouth: 'flat' },
  talking: { eyes: 'neutral', brows: 'raised', mouth: 'talk-small' },
  approval: { eyes: 'wide', brows: 'raised', mouth: 'o' },
  happy: { eyes: 'happy', brows: 'raised', mouth: 'happy' },
  sad: { eyes: 'sad', brows: 'sad', mouth: 'sad' },
  sleeping: { eyes: 'sleepy', brows: 'neutral', mouth: 'flat' },
}

/** Timed cues inside a clip (animation-events.json). */
export type AnimationEvent =
  | { t: number; type: 'blink' }
  | { t: number; type: 'expression'; face: Partial<FaceState>; duration: number }
  | { t: number; type: 'prop'; visible: boolean }
  | { t: number; type: 'sparkle' }
  | { t: number; type: 'squash'; amount: number }

// ---- profile ----

export interface CompanionLook {
  rig: RigId
  /** `head` is required; other slots may be empty. */
  parts: { [S in PartSlot]: string | null }
  face: { eyes: string; brows: string; mouth: string }
  /** '#rrggbb' per tint. */
  colors: Record<Tint, string>
  /** RP-120: fine adjustments, each from -1 to 1; a missing value is 0, the part as drawn. Absent on older looks and files. */
  adjust?: LookAdjust
}

/** RP-120: the part adjustments, in the order the sliders show them. */
export const LOOK_ADJUST_KEYS = [
  'headSize',
  'earHeight',
  'eyeSize',
  'eyeSpacing',
  'eyeHeight',
  'mouthSize',
  'mouthHeight',
  'browSize',
  'browHeight',
  'browTilt',
  'accessorySize',
  'accessoryHeight',
] as const
export type LookAdjustKey = (typeof LOOK_ADJUST_KEYS)[number]
export type LookAdjust = Partial<Record<LookAdjustKey, number>>
/** Every adjustment runs from -LOOK_ADJUST_LIMIT to LOOK_ADJUST_LIMIT in steps of LOOK_ADJUST_STEP. */
export const LOOK_ADJUST_LIMIT = 1
export const LOOK_ADJUST_STEP = 0.05
/** The slider groups and labels, Atelier's own words. */
export const LOOK_ADJUST_GROUPS: ReadonlyArray<{ id: 'head' | 'eyes' | 'mouth' | 'brows' | 'accessory'; label: string; keys: ReadonlyArray<{ key: LookAdjustKey; label: string }> }> = [
  { id: 'head', label: 'Head', keys: [{ key: 'headSize', label: 'Head size' }, { key: 'earHeight', label: 'Ear height' }] },
  { id: 'eyes', label: 'Eyes', keys: [{ key: 'eyeSize', label: 'Eye size' }, { key: 'eyeSpacing', label: 'Eye spacing' }, { key: 'eyeHeight', label: 'Eye height' }] },
  { id: 'mouth', label: 'Mouth', keys: [{ key: 'mouthSize', label: 'Mouth size' }, { key: 'mouthHeight', label: 'Mouth height' }] },
  { id: 'brows', label: 'Brows', keys: [{ key: 'browSize', label: 'Brow size' }, { key: 'browHeight', label: 'Brow height' }, { key: 'browTilt', label: 'Brow tilt' }] },
  { id: 'accessory', label: 'Accessories', keys: [{ key: 'accessorySize', label: 'Accessory size' }, { key: 'accessoryHeight', label: 'Accessory height' }] },
]

export interface CompanionProfile {
  name: string
  /** A preset id, or 'custom'. Presets carry a personality for the agent. */
  persona: string
  look: CompanionLook
  /** macOS: show the companion as the Dock icon (rendered off-screen). */
  dockIcon: boolean
}

export const DEFAULT_LOOK: CompanionLook = {
  rig: 'A',
  parts: { head: 'head-round', ears: null, hair: 'hair-tuft', hat: null, eyeAccessory: null, earAccessory: null, prop: null },
  face: { eyes: 'eyes-round', brows: 'brows-soft', mouth: 'mouth-smile' },
  colors: { skin: '#8f74f8', hair: '#4b3aa8', accent: '#c9bbff', outfit: '#6a4bff' },
}

export const DEFAULT_PROFILE: CompanionProfile = { name: 'Pip', persona: 'pip', look: DEFAULT_LOOK, dockIcon: false }

// ---- generated asset files (served from /companion/ next to the UI) ----

export const COMPANION_ASSET_BASE = 'companion/'

export interface PartDef {
  slot: PartSlot
  label: string
  /** Path under the asset base, e.g. 'parts/hat-beanie.glb'. */
  file: string
  /** Tints used by its materials. */
  tints: Tint[]
}

export interface FacePartDef {
  label: string
  /** SVG path per variant, each a full 512×256 transparent layer. */
  variants: Record<string, string>
  /** Eyes only: a pupil layer moved by gaze, and the variants that show it. */
  pupils?: string
  pupilVariants?: EyeVariant[]
}

export interface RigDef {
  label: string
  file: string
}

/** manifest.json */
export interface CompanionManifest {
  version: 1
  rigs: Record<RigId, RigDef>
  parts: Record<string, PartDef>
  face: Record<FaceLayer, Record<string, FacePartDef>>
  config: {
    compatibility: string
    hats: string
    pupils: string
    randomization: string
    animationEvents: string
    presets: string
  }
}

/**
 * head-part-compatibility.json: per head, the parts it accepts ('all' = any).
 * Entries keyed by a hat id list what a look wearing that hat accepts (in
 * practice, the hair that stays under it).
 */
export type CompatibilityConfig = Record<string, { [S in Exclude<PartSlot, 'head' | 'prop'>]: string[] | 'all' }>

/** A placement tweak in the anchor's local space; rotation in radians (XYZ). */
export interface PartAdjustment {
  offset: [number, number, number]
  rotation: [number, number, number]
  scale: number
}

/**
 * hat-config.json: for every part worn over the head (each hat, plus
 * headphones), a per-head adjustment applied on top of its anchor. Hair
 * raises the seat, so `hair` replaces the adjustment when that hair is worn.
 */
export type HatConfig = Record<string, Record<string, PartAdjustment & { hair?: Record<string, PartAdjustment> }>>

/** eye-pupil-config.json: per eyes id, how far pupils move (fraction of canvas) and their scale. */
export type PupilConfig = Record<string, { rangeX: number; rangeY: number; scale: number }>

/** randomization-config.json */
export interface RandomizationConfig {
  rig: Array<{ id: RigId; weight: number }>
  slots: { [S in PartSlot]: Array<{ id: string | null; weight: number }> }
  face: { [L in FaceLayer]: Array<{ id: string; weight: number }> }
  palettes: Array<{ name: string; weight: number; colors: Record<Tint, string> }>
}

/** animation-events.json */
export type AnimationEventsConfig = Record<ClipId, AnimationEvent[]>

/** presets.json: original preset companions. */
export interface CompanionPreset {
  id: string
  name: string
  tagline: string
  /** One or two sentences appended to the agent's system prompt. */
  personality: string
  look: CompanionLook
  // ── D:L7 preset extras ── (C18: the preset detail sheet and preset updates; `tagline` already exists)
  summary?: string
  starterSkills?: unknown[]
  starterRoutines?: unknown[]
  /** Bumped when Atelier ships a changed preset, so companions made from it can review the update. */
  version?: string
  // ── end D:L7 ──
}

// ---- several companions ----

/** A companion in the user's list. The first one migrated from the single profile keeps the id 'companion-1'. */
export interface Companion extends CompanionProfile {
  id: string
  /** Hidden companions leave the switcher and new-tab picker but keep their chats. */
  hidden: boolean
  /** Standing instructions, added to the system prompt of this companion's new chats. */
  instructions: string
  /** Defaults for this companion's new chats; null follows the global setting. */
  model: string | null
  effort: CompanionEffort | null
  /** ST-58: the engine for this companion's new chats; null or absent follows the global setting. Local to this Mac, never exported. */
  engine?: CompanionEngine | null
  createdAt: number
}

/** Same values as Effort in ipc.ts; kept local so the asset generator can load this file alone. */
export type CompanionEffort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'

/** Same values as EngineId in engine.ts, kept local for the same reason. */
export type CompanionEngine = 'api-key' | 'claude-code'

export const COMPANION_INSTRUCTIONS_MAX = 4000
export const COMPANION_NAME_MAX = 24

// ---- .ateliercompanion files ----

export const COMPANION_FILE_FORMAT = 'atelier-companion'
/** Files with a higher version come from a newer Atelier and are refused with a clear message. */
export const COMPANION_FILE_VERSION = 1
export const COMPANION_FILE_EXTENSION = 'ateliercompanion'

/** The JSON inside a .ateliercompanion file. Skills, routines and memory are present only when the exporter chose them. */
export interface CompanionFile {
  format: typeof COMPANION_FILE_FORMAT
  version: number
  exportedAt: string
  name: string
  persona: string
  look: CompanionLook
  instructions: string
  model: string | null
  effort: CompanionEffort | null
  /** A short note from whoever exported it. */
  note?: string
  /** The companion's own skills: SKILL.md's parts, and their supporting text files (each up to COMPANION_SKILL_FILE_MAX_BYTES). */
  skills?: CompanionFileSkill[]
  routines?: Array<{ name: string; prompt: string; schedule: CompanionFileSchedule }>
  memory?: Array<{ path: string; text: string }>
}

/** One of the companion's own skills in a .ateliercompanion file. Files from before steps and files travelled have neither. */
export interface CompanionFileSkill {
  name: string
  description: string
  instructions: string
  steps?: Array<{ title: string; instructions: string }>
  files?: Array<{ path: string; text: string }>
}

/** A skill's supporting text file travels in a companion file up to this size; bigger ones stay behind. */
export const COMPANION_SKILL_FILE_MAX_BYTES = 256 * 1024

/** Same shape as RoutineSchedule in services.ts. */
/** D:L3: D's schedules, plus A0's hourly interval in files exported before D. */
export type CompanionFileSchedule = unknown | unknown

/** What the review sheet shows before an import is added. Pass `token` to companions.confirmImport. */
export interface CompanionImportPreview {
  token: string
  version: number
  /** The name it will get; a clash with an existing companion adds a suffix. */
  name: string
  originalName: string
  persona: string
  look: CompanionLook
  note: string | null
  instructions: string
  model: string | null
  effort: CompanionEffort | null
  skills: Array<{ name: string; description: string }>
  /** Imported routines are added paused. */
  routines: Array<{ name: string; schedule: CompanionFileSchedule }>
  memoryFiles: number
}
